def find_path(graph, start, goal):
    # Initialize the frontier and explored sets
    frontier = {start}
    explored = set()

    # Initialize the predecessor dictionary
    predecessor = {start: None}

    # Initialize the path to be returned, starting with the start node
    path = [start]

    while frontier:
        # Get the current node from the frontier
        current = None
        for node in frontier:
            if current is None or len(graph[node]) > len(graph[current]):
                current = node

        # If we reached the goal, reconstruct and return the path
        if current == goal:
            while current:
                path.insert(0, current)
                current = predecessor[current]
            return path

        # Mark the current node as explored
        explored.add(current)

        # Explore the neighbors of the current node
        for neighbor in graph[current]:
            if neighbor not in frontier and neighbor not in explored:
                frontier.add(neighbor)
                predecessor[neighbor] = current

    return None
