def find_path(graph, start, goal):
    # Initialize the path and previous node dictionaries
    path = {}
    previous = {}
    for node in graph:
        path[node] = None  # No previous node for any node at the start
        previous[node] = None

    # Queue for BFS
    queue = [start]

    # Mark the start node as visited
    visited = {start}
    while queue:
        current = queue.pop(0)

        # Check if we have reached the goal
        if current == goal:
            path[goal] = current
            return reconstruct_path(path, start, goal)

        # Explore neighbors
        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)
                path[neighbor] = current
                previous[neighbor] = current

    # If we reach here, the goal is unreachable
    return None

def reconstruct_path(path, start, goal):
    path_list = []
    while goal != start:
        path_list.append(goal)
        goal = path[goal]
    path_list.append(start)
    path_list.reverse()
    return path_list
