def find_path(graph, start, goal):
    """
    This function finds a path from start to goal in a directed graph.
    It returns a list of nodes in the path if such a path exists, or None otherwise.
    """
    if start not in graph or goal not in graph:
        return None

    # Initialize the path and visited nodes
    path = []
    visited = set()

    def search(current_node):
        visited.add(current_node)
        if current_node == goal:
            return True
        for neighbor in graph[current_node]:
            if neighbor not in visited:
                if search(neighbor):
                    path.append(neighbor)
                    return True
        return False

    search(start)
    if not path:
        return None
    return path
