    def find_shortest_path(visited, parent, to_visit):
        if to_visit in visited:
            return None
        if to_visit == goal:
            return []
        for neighbor in graph[to_visit]:
            updated_parent = find_shortest_path(visited, parent, neighbor)
            if updated_parent is not None:
                parent[neighbor] = to_visit
                return [neighbor] + updated_parent
        return None

    visited = set()
    parent = {node: None for node in graph}
    to_visit = start
    shortest_path = find_shortest_path(visited, parent, to_visit)

    if shortest_path is None:
        return None

    path = []
    while shortest_path is not None:
        path.append(shortest_path[0])
        shortest_path = parent[shortest_path[0]]
    return path[::-1]  # Reverse the list to get the correct path
