def find_path(graph, start, goal):
    def dfs(node, path, visited):
        if node == goal:
            return path + [node]

        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                result = dfs(neighbor, path + [node], visited)
                if result:
                    return result
        return None

    visited = set()
    return dfs(start, [start], visited)

